import{_ as o,C as a,c as r,o as i,al as s,G as n}from"./chunks/framework.BfTuqGjy.js";const c="/hypermedia-docs/img/hypermea-logo.svg",d="/hypermedia-docs/img/halchemy-logo.svg",y=JSON.parse('{"title":"Quickstart","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://pointw-dev.github.io/hypermedia-docs/introduction/quickstart.html"}]]},"headers":[],"relativePath":"introduction/quickstart.md","filePath":"introduction/quickstart.md"}'),h={name:"introduction/quickstart.md"};function l(p,e,m,u,_,g){const t=a("comments-section");return i(),r("div",null,[e[0]||(e[0]=s('<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>It may surprise some that the hypermedia approach described here predates SOAP. I believe the reason hypermedia feels new to many is: approaches like SOAP created a need for tooling which vendors of the day created and sold. There was no money to be made in hypermedia, and related ideas.</p><p>When REST started to overtake SOAP, the hypermedia aspect of it did not get the tooling attention it deserved. So developers focused on the CRUD aspects of REST and were exposed to the idea. Those that were didn&#39;t have an easy way to experiment with it.</p><p>At <strong>pointw.com</strong> we are contributing to this tool gap.</p><p>To embrace the hypermedia approach, both client and backend have to commit. So we have created two sets of tools:</p><ul><li><img src="'+c+'" width="32"><a href="https://pointw-dev.github.io/hypermea/" target="_blank" rel="noreferrer">hypermea</a> 0.9.38 - <em>Simple Commands, Serious APIs</em><ul><li>Create production-ready hypermedia APIs - <em>fast</em></li><li>This is a <strong>beta</strong> release</li><li>We have been using hypermea internally for years to create real-life production microservice clusters.</li><li>We are in the process of shrink-wrapping the package and polishing the documentation.</li><li>Version 1.0.0 is coming soon. Until its release, proceed with caution.<br><br></li></ul></li><li><img src="'+d+'" width="32"><a href="https://github.com/pointw-dev/halchemy" target="_blank" rel="noreferrer">halchemy</a> 1.0.3 - <em>HAL for humans</em><ul><li>Create clients for HAL-based APIs with ease and without compromise</li></ul></li></ul>',6)),n(t,{repo:"pointw-dev/hypermedia-docs",repoId:"R_kgDOODT1fw",category:"General",categoryId:"DIC_kwDOODT1f84CoFLx"})])}const k=o(h,[["render",l]]);export{y as __pageData,k as default};
